code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                points[value] = (r, c)

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    paths = {}
    for color, (r, c) in points.items():
        if color == 1:
            path = [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
            for rr, cc in path[:-1]:
                put(rr, cc, 5)
            put(*path[-1], 1)
            paths[color] = set(path) | {(r, c)}
        elif color == 2:
            path = [(r, cc) for cc in range(c - 4, c)]
            for rr, cc in path:
                put(rr, cc, 5)
            if path:
                put(*path[0], 2)
            paths[color] = set(path) | {(r, c)}
        elif color == 3:
            path = [(rr, c) for rr in range(r + 1, r + 4)]
            for rr, cc in path[:-1]:
                put(rr, cc, 5)
            if path:
                put(*path[-1], 3)
            paths[color] = set(path) | {(r, c)}
        elif color == 6:
            path = [(rr, c) for rr in range(r - 6, r)]
            for rr, cc in path[1:]:
                put(rr, cc, 5)
            if path:
                put(*path[0], 6)
            paths[color] = set(path) | {(r, c)}

    if 2 in paths:
        for vertical in (3, 6):
            if vertical in paths:
                for r, c in paths[2] & paths[vertical]:
                    put(r, c, 4)
                    length = vertical
                    for step in range(1, length + 1):
                        rr, cc = r + step, c - step
                        if not (0 <= rr < h and 0 <= cc < w):
                            break
                        put(rr, cc, 4)
    return out
'''
